//! What players place in the room, which the replay draws: totems, a
//! warlock's gates, rings, zones, statues, sigils and traps. For each
//! spell that places one, how the log tells where it stands (`Found`),
//! how it is drawn (`Form`), its reach and how long it stands.
//!
//! The table (`placed_spells.rs`) is GENERATED by tools/gen-placed-spells.sh
//! from a list curated in tools/extract/src/placegen.rs: the client's
//! tables prove each entry's name and give its reach and duration, and a
//! census of real logs (tools/placed-spells-census.csv) shows the log
//! writing every spell an entry names. The history store's replay cut
//! keeps the lines of these spells (core's `replay::cut`, through the
//! daemon's `PlacedTable` over this table), and the replay draws them by
//! it: it lives here, beside the store's codecs, because the daemon and a
//! pure client both read it (CONTRACT.md, R29).
//!
//! Each edition of the game has its own table, or none: every question
//! names the edition the log was written by (`Edition::counts_as`, a log
//! that names none counting as Retail), and an edition with no table
//! places nothing and tells nothing, never another edition's entry.
//! Retail's is the only one generated so far.

use wowdps_model::Edition;

mod placed_spells;

/// Each edition's table, by the edition it counts as. A table generated
/// for another edition is one entry here.
static TABLES: &[(Edition, &[Placed])] = &[(Edition::Retail, placed_spells::TABLE)];

/// How the log tells where a placed spell stands. An entry lists what
/// tells, most trusted first; the replay takes the first that does.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Found {
    /// The unit its summon made, wherever the log posts it: a totem's own
    /// casts carry its position, so a totem moved is seen moved.
    Unit,
    /// Where the units these spells reached stood when they did: an aura
    /// put on them, or a heal or a hit landing on them.
    Touch(&'static [u32]),
    /// Where its caster stood as it was cast.
    Caster,
    /// Where the unit its cast was aimed at stood.
    Target,
    /// A Demonic Gateway's far gate: where the travelers this aura marks
    /// (once a trip) leave from or land, the near gate being where its
    /// caster stood.
    Trips(u32),
    /// Where the enemies it threw out of it were thrown from (Ring of
    /// Peace, whose log line is its cast alone).
    Thrown,
}

/// What a placed spell is for: how it matters in a fight, and how loudly
/// the replay draws it.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Purpose {
    /// A way across the room: a gateway, a speed totem, a feather, a
    /// circle or spirit to come back to.
    Way,
    /// Crowd control: a ring, a sigil, a trap, a stun or grip.
    Control,
    /// A raid's wall against damage: a barrier, a zone, Spirit Link.
    Wall,
    /// Healing where it stands: a healing totem, a carpet, a statue.
    Heal,
}

/// How a placed spell is drawn.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Form {
    /// An area: its reach as a disc round where it stands.
    Area,
    /// A ring: its reach as the ring's line (Ring of Frost, whose middle
    /// is no part of it).
    Ring,
    /// Two gates and the way between them (Demonic Gateway).
    Gate,
    /// A thing standing at a point, whatever reaches it (a statue, a
    /// healing totem, a circle to come back to).
    Post,
}

/// A spell that places something in the room.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Placed {
    /// The spell a player casts to place it: the summon's own, for a
    /// summoned unit (the log's SPELL_SUMMON names it).
    pub spell: u32,
    pub name: &'static str,
    pub purpose: Purpose,
    /// What tells where it stands, most trusted first.
    pub found: &'static [Found],
    pub form: Form,
    /// Its reach in yards; 0 where none is drawn.
    pub reach: f32,
    /// How long it stands from its cast, in ms; 0 for one that is gone as
    /// it lands (drawn as a flash).
    pub lasts_ms: u32,
    /// How long its caster waits to place it again (ms): its cooldown, or its
    /// charges' recharge, from the client, before talents.
    pub cooldown_ms: u32,
    /// Whether it stands only until the first unit it touches (a trap, a
    /// feather), `lasts_ms` at most.
    pub until_touched: bool,
}

impl Placed {
    /// Every spell id the log may tell where it stands by: its `Touch` and
    /// `Trips` spells.
    pub fn telling(&self) -> impl Iterator<Item = u32> + '_ {
        self.found.iter().flat_map(|f| match f {
            Found::Touch(ids) => ids.to_vec(),
            Found::Trips(id) => vec![*id],
            _ => Vec::new(),
        })
    }
}

/// The editions that have a table, each once.
pub fn editions() -> impl Iterator<Item = Edition> {
    TABLES.iter().map(|&(edition, _)| edition)
}

/// Every placed spell of `edition`'s table, by spell id; none for an
/// edition with no table.
pub fn all(edition: Edition) -> &'static [Placed] {
    let edition = edition.counts_as();
    TABLES
        .iter()
        .find(|&&(e, _)| e == edition)
        .map_or(&[], |&(_, table)| table)
}

/// The placed spell a cast or summon of `spell` makes in `edition`, if any.
pub fn placed(edition: Edition, spell: u32) -> Option<&'static Placed> {
    let table = all(edition);
    table
        .binary_search_by_key(&spell, |p| p.spell)
        .ok()
        .and_then(|i| table.get(i))
}

/// Whether `spell` tells where some placed spell of `edition` stands (a
/// `Touch` or `Trips` spell of any entry).
pub fn tells(edition: Edition, spell: u32) -> bool {
    all(edition)
        .iter()
        .any(|p| p.telling().any(|id| id == spell))
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Retail's table answers for Retail and for a log that names no
    /// edition; every other edition has none, so a lookup there, of a
    /// spell Retail's table holds or of one no table holds, is nothing.
    #[test]
    fn an_edition_with_no_table_places_and_tells_nothing() {
        let gateway = 111_771;
        let trip = 113_942;
        for e in [Edition::Retail, Edition::Unknown(0)] {
            assert!(placed(e, gateway).is_some(), "{e:?}");
            assert!(tells(e, trip), "{e:?}");
            assert!(!all(e).is_empty(), "{e:?}");
        }
        for e in [Edition::Forever, Edition::Classic(2), Edition::Unknown(7)] {
            assert!(all(e).is_empty(), "{e:?}");
            for id in [gateway, trip, 0, u32::MAX] {
                assert!(placed(e, id).is_none(), "{e:?} {id}");
                assert!(!tells(e, id), "{e:?} {id}");
            }
        }
        for id in [0, u32::MAX] {
            assert!(placed(Edition::Retail, id).is_none(), "{id}");
            assert!(!tells(Edition::Retail, id), "{id}");
        }
        assert_eq!(editions().collect::<Vec<_>>(), [Edition::Retail]);
    }

    /// Every table is sorted by spell id, as `placed`'s search needs, and
    /// listed once under the edition it counts as.
    #[test]
    fn every_table_is_sorted_and_listed_once() {
        for (i, &(e, table)) in TABLES.iter().enumerate() {
            assert_eq!(e, e.counts_as());
            assert!(
                TABLES.iter().skip(i + 1).all(|&(o, _)| o != e),
                "{e:?} twice"
            );
            assert!(table.windows(2).all(|w| w[0].spell < w[1].spell), "{e:?}");
        }
    }

    /// Retail's placed table was made from a client no older than the
    /// patch `Edition::tables_patch` names for Retail (core holds that patch
    /// to its own tables, the oldest of them): this table, regenerated
    /// alone from an older client, would make the patch claim too much.
    #[test]
    fn the_table_is_no_older_than_its_editions_tables_patch() {
        let text = include_str!("placed/placed_spells.rs");
        let line = text
            .lines()
            .find(|l| l.starts_with("//! Source:"))
            .expect("a Source line");
        let build = line.split("build ").nth(1).expect("a build");
        let n: Vec<u16> = build
            .split(|c: char| !c.is_ascii_digit())
            .take(3)
            .map(|p| p.parse().expect("a number"))
            .collect();
        let patch = (n[0], n[1], n[2]);
        let tables = Edition::Retail.tables_patch().expect("Retail has tables");
        assert!(patch >= tables, "{patch:?} is older than {tables:?}");
    }
}
